// Static reference data generated by tools/sync-db.mjs from ragassets' copies of
// the LATAM client's data tables (see README). Loaded once at startup.

import { CACHE_BUST, RAGASSETS_BASE } from "./state";

export type Slot = "top" | "mid" | "low" | "garment";
export const SLOTS: Slot[] = ["top", "mid", "low", "garment"];

export type Costume = {
  id: number;
  name: string;
  /** Sprite view id (the client's ClassNum, or recovered from the resource name
   *  when ClassNum is 0) — absent when the item has none. */
  view?: number;
  /** Visual slot(s) the item occupies (multi-slot costumes cover several). */
  slots: Slot[];
  /** Which ragassets param the view id must be sent as, when that disagrees with
   *  the slot. Absent (the norm) means the slot decides: `garment` for Capa,
   *  `headgear` for the head slots. A few items' description slot doesn't match
   *  the sprite table their ClassNum lives in — see tools/sync-db.mjs. */
  viewKind?: "headgear" | "garment";
  /** World-effect key (a ".str" aura / falling-petals etc.) played on the
   *  character by the game's effect system rather than drawn into its sprite.
   *  Assets are served by ragassets at /effects/<effect>/ (see sim/effect.ts).
   *
   *  NOT a statement about the sprite: a costume can have both a view and an
   *  effect — "[Visual] Escudo Poenitentia" (420382) draws a shield AND plays
   *  the atque_poenitentia aura over it. Only the rows from /effects/index.json
   *  are view-less by construction (see loadDb). */
  effect?: string;
  /** The same thing for a hat effect the client plays as a looping .spr/.act
   *  attached to the character instead of as a ".str" — "[Visual] Aura de
   *  Betelgeuse" (400149) and its two siblings.
   *
   *  Resolved at load (`hatSprite`) rather than stored as the bare bundle key,
   *  so the bundle→placement question is answered once here and whoever draws it
   *  is left with pure selection.
   *
   *  Exclusive with `effect`: the published row carries one or the other, never
   *  both, because the client's hat-effect table names a single resource file
   *  per costume and its extension is what decides which system plays it. */
  attachment?: BuiltinSprite;
};

/** How a costume's view id must be rendered — its `viewKind` when present, else
 *  the slot's default. */
export function viewKindOf(item: Pick<Costume, "slots" | "viewKind">): "headgear" | "garment" {
  return item.viewKind ?? (item.slots.includes("garment") ? "garment" : "headgear");
}

/** The bundle keys and placement numbers ragassets publishes for one footprint
 *  costume, straight from the client's `FootPrintEffectTable`.
 *
 *  A footprint isn't one looping effect like an aura: the client stamps a decal
 *  at each footstep out of a `bottom` effect (the mark on the ground) and an
 *  optional `top` (the puff above it), spaced and offset by these numbers. They
 *  are the client's own values, passed through unconverted — see
 *  sim/render/footprint.ts for the one unit conversion this app makes. */
export type FootprintSteps = {
  bottomLeft: string;
  bottomRight: string;
  topLeft?: string;
  topRight?: string;
  scaleBottom: number;
  scaleTop: number;
  /** How far above the ground the top effect plays. */
  heightTop: number;
  /** Distance between successive prints, and how far each sits off the walk line. */
  stride: number;
  gap: number;
  /** Whether the mark rotates to face the direction of travel. */
  adjustAngle: boolean;
};

/** A graphic stone the client draws from its own code rather than from a ".str",
 *  reproduced here from the effect's published parameters.
 *
 *  These are the rows whose `HatEffectInfo` entry carries a `hatEffectID` — an
 *  `EF_` id into the client's built-in effect table — instead of a
 *  `resourceFileName`, so there is no file for ragassets to extract. The id
 *  itself is read out of the client's Lua tables; what that id DOES comes from
 *  roBrowser's port of the same effect table, which is where every binary-format
 *  parser in this repo comes from too. Nothing here is inferred from an item
 *  description — see BUILTIN_EFFECT in tools/sync-db.mjs for the sourcing, and
 *  note that most of these effects are in neither source and stay preview-less
 *  rather than being invented.
 *
 *  - `scale`  — the effect only resizes the character (EF 421 sets the entity's
 *    xSize/ySize to 2.5 against a default of 5, i.e. exactly half).
 *  - `sprite` — it plays a looping .spr/.act attached to the character, which
 *    ragassets already bundles at /effects/sprites/<key>/. */
export type BuiltinEffect = { kind: "scale"; scale: number } | BuiltinSprite;

export type BuiltinSprite = {
  kind: "sprite";
  /** Bundle key under /effects/sprites/ (see sim/spriteEffect.ts). */
  key: string;
  /** Anchor at head height rather than at the feet — see `builtinRisePx`. */
  head?: boolean;
  /** The effect's own screen-up offset, in sprite pixels — see `builtinRisePx`. */
  yOffset?: number;
  /** Draw behind the character (`renderBeforeEntities`). */
  behind?: boolean;
};

/** What `head: true` lifts by on its own. Nothing is measured for it: the client
 *  steps the attachment up by this much and no further. */
const HEAD_RISE_PX = 100;

/** How far above the feet a built-in sprite effect plays, in sprite pixels of
 *  screen-up lift.
 *
 *  The client's attachment carries ONE screen offset, not two: an explicit
 *  `yOffset` *replaces* the head anchor instead of stacking on it (roBrowser
 *  `EntityAttachments`: `position[1] = head ? -100 : 0`, reached only when the
 *  row gave no offset of its own). Adding the two is what put Raios Vermelhos —
 *  the one row that declares both — a whole body above the sprite. */
export function builtinRisePx(builtin: BuiltinSprite): number {
  // RO screen y points down, so the table's negative offsets are the ones that lift.
  if (builtin.yOffset !== undefined) return -builtin.yOffset;
  return builtin.head ? HEAD_RISE_PX : 0;
}

/** Whether a built-in sprite effect draws in FRONT of the character, which is
 *  the client's default — only a row that asks to go behind it does.
 *
 *  roBrowser's `EntityAttachments.renderAttachment` gives the attachment
 *  `zIdx = attachment.renderBefore ? 1 : 500`, and the entity itself sits
 *  between the two: a plain attachment is drawn over the body, and
 *  `renderBeforeEntities` (this type's `behind`) is what moves it under. So
 *  Raios Vermelhos (25225) wraps around the character and Espaço Digital
 *  (1002585) stays behind it.
 *
 *  Takes the whole `BuiltinEffect` rather than a `BuiltinSprite`, because both
 *  surfaces hold the broad shape and a `scale` built-in — which draws nothing
 *  of its own — has no layer to ask about. */
export function builtinInFront(builtin: BuiltinEffect | null | undefined): boolean {
  return builtin?.kind === "sprite" && !builtin.behind;
}

/** Where a hat effect's sprite bundle plays, for the bundles whose placement is
 *  not the client's default.
 *
 *  /effects/hat_effects.json publishes a bundle key and nothing else — none of
 *  the client's placement flags — so a hat sprite plays at the feet, over the
 *  body, unless it is listed here. Keyed by bundle rather than by item, because
 *  that is what the client's own attachment carries; the whole `BuiltinSprite`
 *  placement is expressible, not just the layer.
 *
 *  `digital_space` is listed because its bundle is the sprite the client's EF
 *  1240 plays with `renderBeforeEntities` — the same row sync-db's
 *  BUILTIN_EFFECT already records for the "Espaço Digital" stone, out of
 *  roBrowser's port of that table. Drawn in front, its screen-filling hologram
 *  hides the character instead of decorating it. (The stone and the hat effect
 *  reach the same art under two different bundle names, `eff_1240` and
 *  `digital_space`, so a correction to one belongs in the other.) */
const SPRITE_PLACEMENT = new Map<string, Partial<BuiltinSprite>>([
  ["digital_space", { behind: true }],
]);

/** The attachment a hat-effect costume's sprite bundle plays as. One canonical
 *  object per bundle: both render surfaces are fed this every frame and compare
 *  by key, and the stone path beside it hands out the db's own object too. */
const attachments = new Map<string, BuiltinSprite>();

export function hatSprite(key: string): BuiltinSprite {
  let made = attachments.get(key);
  if (!made) {
    made = { kind: "sprite", key, ...SPRITE_PLACEMENT.get(key) };
    attachments.set(key, made);
  }
  return made;
}

/** Whether anything will actually be drawn for this stone. Three different
 *  mechanisms can supply it — a ".str" bundle, a footprint trail, or the client's
 *  own built-in effect table — and every caller wants the same answer, so it
 *  lives here rather than being spelled out at each call site (it had already
 *  drifted into three copies that disagreed). */
export function canPreview(stone: Stone): boolean {
  return !!(stone.effect || stone.steps || stone.builtin);
}

/** A "Pedra Gráfica" — the graphic-effect enchant the Loja Fashion puts INSIDE a
 *  costume (browiki "Encantamento de Visual"). It never occupies a visual slot
 *  of its own: a character wears a Topo costume *and* has a Topo stone enchanted
 *  into it, so stones live in their own build layer (`State.enchants`).
 *
 *  Shaped as a Costume so the catalogue's tiles, rows, icons and market links
 *  take one without changes — `stone: true` is what tells the two apart at the
 *  points where the behaviour differs (equipping, and the slot cards). `slots`
 *  always holds exactly the one position the stone is locked to; `slot` is that
 *  same position, unwrapped, for the code that only ever wants the one. */
export type Stone = Costume & {
  stone: true;
  slot: Slot;
  /** True for the "Pegadas" — the stones the client draws per footstep rather
   *  than as one effect on the body. Set even when `steps` is absent, which is
   *  how the UI tells "appears when you walk, not extracted yet" apart from an
   *  effect the client keeps in its own code and nothing can ever draw. */
  footprint?: true;
  /** How to draw that trail, when ragassets has published the bundles. */
  steps?: FootprintSteps;
  /** Drawn from the client's built-in effect table rather than from a .str. */
  builtin?: BuiltinEffect;
};

export type PaletteInfo = {
  count: number;
  /** Representative hex color per palette index (null when unsampled). */
  swatches: (string | null)[];
};

export type ClassInfo = {
  id: number;
  jt: string;
  name: string;
  group: string;
  race: "human" | "doram";
  /** Clothes-color palettes per gender; a missing gender has no palette files
   *  (gender-locked classes like Trovador/Musa have exactly one entry). */
  palettes: Partial<Record<"m" | "f", PaletteInfo>>;
  /** Alternative outfits ("estilo de roupa"): the extra body sprites the client
   *  ships for the 3rd classes and a few 4th ones, selected with ragassets'
   *  `outfit=` param. Each carries its OWN clothes palettes — a different set
   *  from the normal body's, sometimes empty (the outfit then has no dyes).
   *  Absent for the classes with no alternative outfit (most of them). */
  outfits?: { n: number; palettes: Partial<Record<"m" | "f", PaletteInfo>> }[];
  /** True when the class has no party icon in the client — unreleased on LATAM. */
  unreleased?: boolean;
};

export type HairSet = {
  styles: { n: number; colors: number }[];
  swatches: (string | null)[];
};

export type HairDb = Record<"human" | "doram", Record<"m" | "f", HairSet>>;

export type Db = {
  classes: ClassInfo[];
  hair: HairDb;
  costumes: Costume[];
  stones: Stone[];
};

/** The stones file stores each stone's one position as `slot`; the rest of the
 *  app treats a stone as a Costume, which carries `slots`. Widen on read so
 *  both spellings are there and neither side has to remember the other's. */
type RawStone = {
  id: number;
  name: string;
  slot: Slot;
  effect?: string;
  footprint?: true;
  steps?: FootprintSteps;
  builtin?: BuiltinEffect;
};

/** One row of ragassets' hat-effect catalogue (/effects/hat_effects.json): a
 *  costume whose client hat-effect entry names a resource file, with the bundle
 *  ragassets extracted from it.
 *
 *  A DIFFERENT set from /effects/index.json, and deliberately disjoint from it.
 *  Membership in the index means "this costume draws no sprite, draw the effect
 *  instead", which is why tools/sync-db.mjs deletes those ids from
 *  costumes.json. These costumes mostly DO draw a sprite and must keep it — so
 *  they are merged onto the committed rows rather than replacing them (see
 *  `withHatEffects`), and their ids must never reach sync-db's drop list.
 *
 *  Merged at load rather than baked into costumes.json by sync-db, which would
 *  otherwise be the natural place: tools/verify-previews.mjs rewrites that file
 *  down to {id,name,slots,view,viewKind} and would strip the keys straight back
 *  off, and it would prune the rows whose effect is the whole costume as
 *  costumes that render blank — which they do. Reading it at runtime also means
 *  a hat effect ragassets publishes tomorrow lights up without a sync commit,
 *  the same property /effects/index.json already has. */
export type HatEffectRow = {
  id: number;
  name: string;
  slots: Slot[];
  /** A ".str" bundle, at /effects/<effect>/. */
  effect?: string;
  /** A played .spr/.act bundle, at /effects/sprites/<sprite>/. */
  sprite?: string;
};

/** What a hat-effect row gives the costume, or null when ragassets found the
 *  costume's hat effect but no bundle for it. */
function bundleOf(row: HatEffectRow): Pick<Costume, "effect" | "attachment"> | null {
  if (row.effect) return { effect: row.effect };
  if (row.sprite) return { attachment: hatSprite(row.sprite) };
  return null;
}

/** Attach each hat effect to its costume, appending the ones the catalogue
 *  doesn't already hold.
 *
 *  Most rows name a costume that is already in costumes.json with a real view:
 *  those keep everything they have — name, view, viewKind — and only gain the
 *  effect, so the character still renders and the effect plays over it. The
 *  committed row wins on name: it comes from the same client item table and
 *  carries the pins in sync-db's ITEM_TEXT_OVERRIDE.
 *
 *  The rest have no costume row to join, for one of two reasons that end the
 *  same way: the item's sprite view is 0 ("Aura de Betelgeuse" is a hat effect
 *  and nothing else), or it has a view whose sprite renders blank and
 *  tools/verify-previews.mjs pruned it. Either way the effect is the whole
 *  costume, so the row is appended view-less — exactly the shape the
 *  /effects/index.json rows arrive in, which every surface already handles. */
export function withHatEffects(costumes: Costume[], rows: HatEffectRow[]): Costume[] {
  const pending = new Map(rows.filter(bundleOf).map((row) => [row.id, row]));
  const out = costumes.map((costume) => {
    const row = pending.get(costume.id);
    if (!row) return costume;
    pending.delete(costume.id);
    return { ...costume, ...bundleOf(row) };
  });
  for (const row of pending.values()) {
    out.push({ id: row.id, name: row.name, slots: row.slots, ...bundleOf(row) });
  }
  return out;
}

export async function loadDb(): Promise<Db> {
  const [classes, hair, costumes, stones, effects, hatEffects] = await Promise.all([
    fetchJson<{ classes: ClassInfo[] }>("db/classes.json"),
    fetchJson<HairDb>("db/hair.json"),
    fetchJson<{ items: Costume[] }>("db/costumes.json"),
    fetchJson<{ items: RawStone[] }>("db/stones.json"),
    // Effect-only costumes: auras, falling petals, spotlights — drawn by the
    // client's .str effect system rather than as a body sprite, so view-less,
    // and dropped from costumes.json by sync-db precisely because they are here.
    ragCatalogue<Costume>("index"),
    // Hat-effect costumes: the ones that play an effect *as well as* drawing
    // their own sprite, plus the few that are nothing but the effect. A
    // different set from the index above, meaning the opposite thing about the
    // sprite — see HatEffectRow.
    ragCatalogue<HatEffectRow>("hat_effects"),
  ]);
  const items = withHatEffects([...costumes.items, ...effects.items], hatEffects.items)
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR") || a.id - b.id);
  const stoneItems: Stone[] = stones.items
    .map((s) => ({ ...s, slots: [s.slot], stone: true as const }))
    .sort((a, b) => a.name.localeCompare(b.name, "pt-BR") || a.id - b.id);
  // Drop classes unreleased on LATAM (no party icon) — they shouldn't appear in
  // the picker (or anywhere else).
  const released = classes.classes.filter((c) => !c.unreleased);
  return { classes: released, hair, costumes: items, stones: stoneItems };
}

async function fetchJson<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return res.json() as Promise<T>;
}

/** One of ragassets' /effects catalogues, by filename.
 *
 *  ?v=CACHE_BUST for the same reason the map manifests carry it: these files
 *  have fixed names and immutable cache headers, and the costumes they list are
 *  listed nowhere else — so a browser pinned to last year's copy would lose
 *  every costume added to them since.
 *
 *  A failure is tolerated rather than fatal: a ragassets outage then costs the
 *  effects it would have added, which is a far better load than none. */
function ragCatalogue<T>(name: string): Promise<{ items: T[] }> {
  return fetchJson<{ items: T[] }>(
    `${RAGASSETS_BASE}/effects/${name}.json?v=${CACHE_BUST}`,
  ).catch(() => ({ items: [] }));
}
